const snippets={"Python": ["", "", "class Solution:", "", "    def minDistance(self, word1: str, word2: str) -> int:", "        (m, n) = (len(word1), len(word2))", "        f = [[0] * (n + 1) for _ in range(m + 1)]", "        for j in range(1, n + 1):", "            f[0][j] = j", "        for (i, a) in enumerate(word1, 1):", "            f[i][0] = i", "            for (j, b) in enumerate(word2, 1):", "                if a == b:", "                    f[i][j] = f[i - 1][j - 1]", "                else:", "                    f[i][j] = min(f[i - 1][j], f[i][j - 1], f[i - 1][j - 1]) + 1", "        return f[m][n]"], "Java": ["import java.util.*;", "class Solution {", "    public int minDistance(String word1, String word2) {", "        int m = word1.length(), n = word2.length();", "        int[][] f = new int[m + 1][n + 1];", "        for (int j = 1; j <= n; ++j) {", "            f[0][j] = j;", "        }", "        for (int i = 1; i <= m; ++i) {", "            f[i][0] = i;", "            for (int j = 1; j <= n; ++j) {", "                if (word1.charAt(i - 1) == word2.charAt(j - 1)) {", "                    f[i][j] = f[i - 1][j - 1];", "                } else {", "                    f[i][j] = Math.min(f[i - 1][j], Math.min(f[i][j - 1], f[i - 1][j - 1])) + 1;", "                }", "            }", "        }", "        return f[m][n];", "    }", "}"]};
